@log_input_and_output
def get_geolocation_file_from_smod(download_directory, bts_type, smod_geolocation_path='/ffs/run/config/lifedata',
                                   custom_string='geolocation', slave_bts=False):
    """
    Gets geolocation file from smod. Supports full rack config. If file is not found in the `smod_geolocation_path`,
    it will make another attempt to download the file from '/ffs/run/logs' directory.

    :param download_directory: path to directory where the geolocation files will be downloaded
    :type download_directory: str
    :param bts_type: type of BTS (e.g. 'GNB' or 'ENB')
    :type bts_type: str
    :param smod_geolocation_path: (optional) path to the geolocation file on smod (Default: '/ffs/run/config/lifedata')
    :type smod_geolocation_path: str
    :param custom_string: (optional) unique string that is in a geolocation filename (Default: 'geolocation')
    :type custom_string: str
    :param slave_bts: (optional) True - if config with full rack, False otherwise (Default: False)
    :type slave_bts: bool
    """
    smod, alias = _create_smod_connection(bts_type=bts_type, slave_bts=slave_bts)
    files_list = smod.get_list_of_files_in_directory(directory=smod_geolocation_path)

    log_to_console('Downloading geolocation file from {} smod...'.format('secondary' if slave_bts else 'primary'))
    try:
        _download_single_file_with_custom_string_in_name(custom_string=custom_string,
                                                         files_list=files_list,
                                                         geolocation_path=smod_geolocation_path,
                                                         download_directory=download_directory,
                                                         device=smod,
                                                         custom_prefix_filename='smod{}_'.format(int(slave_bts) + 1))
    except FileWithCustomStringNotFound:
        new_smod_geolocation_path = '/ffs/run/logs'
        files_list = smod.get_list_of_files_in_directory(directory=new_smod_geolocation_path)

        log_to_console(f'No geolocation file found in directory: "{smod_geolocation_path}", '
                       f'trying to download from "{new_smod_geolocation_path}" ...')
        _download_single_file_with_custom_string_in_name(custom_string=custom_string,
                                                         files_list=files_list,
                                                         geolocation_path=new_smod_geolocation_path,
                                                         download_directory=download_directory,
                                                         device=smod,
                                                         custom_prefix_filename='smod{}_'.format(int(slave_bts) + 1))
    smod.close_connection()


@log_input_and_output
def get_geolocation_files_from_bbmods_per_smod(download_directory, bts_type, bbmod_geolocation_path='/run/blackbox',
                                               custom_string='geolocation', slave_bts=False):
    """
    Gets geolocation file from every bbmod (from single smod). Supports full rack config.
    ABIA is not supported by feature CB009077-SR-D and is skipped during downloading.

    :param download_directory: path to directory where the geolocation files will be downloaded
    :type download_directory: str
    :param bts_type: type of BTS (e.g. 'GNB' or 'ENB')
    :type bts_type: str
    :param bbmod_geolocation_path: (optional) path to the geolocation file on bbmod (Default: '/run/blackbox')
    :type bbmod_geolocation_path: str
    :param custom_string: (optional) unique string that is in a geolocation filename (Default: 'geolocation')
    :type custom_string: str
    :param slave_bts: (optional) True - if config with full rack, False otherwise (Default: False)
    :type slave_bts: bool
    """
    smod, smod_alias = _create_smod_connection(bts_type=bts_type, slave_bts=slave_bts)
    bbmods_attributes = smod.get_bbmods_topology_info()
    log_result(bbmods_attributes)

    for bbmod_attributes in bbmods_attributes:
        if bbmod_attributes['hw_name'] == 'ABIA':
            continue
        bbmod = _create_bbmod_connection(bbmod_attributes, smod_alias)
        files_list = bbmod.get_list_of_files_in_directory(directory=bbmod_geolocation_path)
        log_to_console('Downloading geolocation file from bbmod: {} ({} smod)...'.format(
            bbmod_attributes['alias'], 'secondary' if slave_bts else 'primary'))

        _download_single_file_with_custom_string_in_name(
            custom_string=custom_string,
            files_list=files_list,
            geolocation_path=bbmod_geolocation_path,
            download_directory=download_directory,
            device=bbmod,
            custom_prefix_filename='smod{}_{}_'.format(int(slave_bts) + 1, bbmod_attributes['alias']))
        bbmod.close_connection()

    smod.close_connection()


@log_input_and_output
def get_geolocation_files_from_rmods(download_path, connection, path='/mnt/runtime/rfsw/uoam',
                                     file_name='permanent.xml'):
    """
    Gets geolocation file from every rmod. Supports full rack config.

    :param download_path: path to directory where the geolocation files will be downloaded
    :type download_path: str
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param path: (optional) path to the file with geolocation info on rmod
           (Default: '/mnt/runtime/rfsw/uoam')
    :type path: str
    :param file_name: (optional) unique filename which contains rmod geolocation info(Default: 'permanent.xml')
    :type file_name: str
    """
    rmod_indexes = get_rmod_indexes(connection=connection)
    log_to_console('Rmod indexes in configuration: {}'.format(rmod_indexes))
    for rmod_index in rmod_indexes:
        log_to_console('Downloading geolocation file from RMOD-{}...'.format(rmod_index))
        rmod_ops = RmodOperations()
        rmod_ops.get_file_from_rmod(rmod_id=rmod_index, filename=file_name, rmod_path=path,
                                    local_path=download_path, connection=connection)
        move_file_to_target_directory('{}/{}'.format(download_path, file_name),
                                      '{}/RMOD-{}_{}'.format(download_path, rmod_index, file_name))


@log_input_and_output
def verify_rmods_geolocation_files(path_to_files, act_loc_info_store=True):
    """
    Verifies for every xml file in given path if elements with tag 'managedObject' and also with attribute 'distName'
    equals to 'moduleDetectedLocation' and 'moduleConfiguredLocation' exist and have element with tag 'parameter'
    which has two elements:
        1) tag: 'parameterName', text: 'Location'
        2) tag: 'value', text: not None

    :param path_to_files: path to directory with the geolocation xml files.
    :type path_to_files: str
    :param act_loc_info_store: (optional) True - if files are expected to contain geolocation objects, False otherwise
           (Default: True)
    :type act_loc_info_store: bool
    :raises DirectoryIsEmpty: if given directory path is empty
    :raises ObjectNotFoundInXmlFile: if xml file has no element ('managedObject') with attribute 'distName' equals to
            'moduleDetectedLocation' or 'moduleConfiguredLocation'
    :raises LocationInfoNotFoundInXmlFile: if there is no element with tag 'parameter' which contains location info
    :raises ObjectShouldNotBeFoundInXmlFile: if xml file has element ('managedObject') with attribute 'distName'
            equals to 'moduleDetectedLocation' or 'moduleConfiguredLocation'
    """
    attribute_values = ['moduleDetectedLocation', 'moduleConfiguredLocation']
    custom_element_name = 'managedObject'
    custom_attr_name = 'distName'

    file_list = [file for file in os.listdir(path_to_files) if os.path.isfile('{}/{}'.format(path_to_files, file))]
    if not file_list:
        raise DirectoryIsEmpty('Directory {} is empty'.format(path_to_files))

    for xml_file_name in file_list:
        xml_file = XmlFile('{}/{}'.format(path_to_files, xml_file_name))

        for attribute_value in attribute_values:
            if act_loc_info_store:
                _verify_if_geolocation_objects_exist(xml_file=xml_file, xml_file_name=xml_file_name,
                                                     custom_element_name=custom_element_name,
                                                     custom_attr_name=custom_attr_name,
                                                     attribute_value=attribute_value)
            else:
                _verify_if_geolocation_objects_do_not_exist(xml_file=xml_file, xml_file_name=xml_file_name,
                                                            custom_element_name=custom_element_name,
                                                            custom_attr_name=custom_attr_name,
                                                            attribute_value=attribute_value)


@log_input_and_output
def remove_geolocation_parameters_from_prevent_list(prevent_param_modif_list, feature_parameters):
    """
    Removes given parameters (full or partial name) from the prevent parameters modification list

    :param prevent_param_modif_list: prevent parameters modification list from the current BTS configuration,
           e.g.: ['FEATCADM-actLocInfoStore']
    :type prevent_param_modif_list: list of str
    :param feature_parameters: list of full or partial names of parameter that will be searched in the prevent
           parameters modification list, e.g. ['actLocInfoStore']
    :type feature_parameters: list of str
    :return: new prevent parameters modification list without given parameter
    :rtype: list of str
    """
    return [parameter for parameter in prevent_param_modif_list if not any(
        feature_parameter in parameter for feature_parameter in feature_parameters)]


def _create_smod_connection(bts_type, slave_bts=False):
    smod = Smod()

    if slave_bts:
        credentials = get_ssh_connection_credentials(bts_type=bts_type, common_unit_id=1)
        alias = 'slave_bts'
    else:
        credentials = get_ssh_connection_credentials(bts_type=bts_type)
        alias = 'master_bts'
    proxy = None

    if slave_bts:
        proxy = 'slave_bts_vm'
        vm_credentials = TestLine().get_bts_test_pc_credentials(bts_type=bts_type, slave=slave_bts)
        ssh().connect_to(hostname=vm_credentials['host'], username=vm_credentials['user'],
                         password=vm_credentials['password'], alias=proxy)

    smod.connect_to(address=credentials['host'], username=credentials['username'], password=credentials['password'],
                    proxy=proxy, alias=alias)

    return smod, alias


def _create_bbmod_connection(bbmod_attributes, proxy):
    bbmod = Bbmod()

    bbmod.connect_to(address=bbmod_attributes['address'], username=bbmod_attributes['username'],
                     password=bbmod_attributes['password'], proxy=proxy, alias=bbmod_attributes['alias'])

    return bbmod


def _download_single_file_with_custom_string_in_name(custom_string, files_list, geolocation_path, download_directory,
                                                     device, custom_prefix_filename=''):
    files_list_with_custom_str = [file_name for file_name in files_list if custom_string in file_name]

    if len(files_list_with_custom_str) == 0:
        raise FileWithCustomStringNotFound('File with string {} in name is not found in directory: {}.'.format(
            custom_string, geolocation_path))
    elif len(files_list_with_custom_str) > 1:
        raise TooManyFileNamesWithCustomString('There is more than one file with {} string in name in '
                                               'directory: {}.'.format(custom_string, geolocation_path))
    else:
        device.download_file('{}/{}{}'.format(download_directory, custom_prefix_filename,
                                              files_list_with_custom_str[0]),
                             '{}/{}'.format(geolocation_path, files_list_with_custom_str[0]))

    return custom_prefix_filename + files_list_with_custom_str[0]


@log_input_and_output
def _check_if_custom_element_have_location_info(custom_elements_content, custom_element_name, custom_attr_name,
                                                attr_value):
    for custom_element_content in custom_elements_content:
        if custom_element_content['attributes'][custom_attr_name] == attr_value:
            for object_child in custom_element_content['{}_content'.format(custom_element_name)]:
                if object_child['{}_content'.format(object_child['tag'])]:
                    is_location_found = False
                    is_location_value_found = False
                    for object_grandchild in object_child['{}_content'.format(object_child['tag'])]:
                        if object_grandchild['tag'] == 'parameterName' and object_grandchild['text'] == 'Location':
                            is_location_found = True
                        if object_grandchild['tag'] == 'value' and object_grandchild['text'] != 'None':
                            is_location_value_found = True
                        if is_location_found and is_location_value_found:
                            return True

    return False


@log_input_and_output
def _verify_if_geolocation_objects_exist(xml_file, xml_file_name, custom_element_name, custom_attr_name,
                                         attribute_value):
    custom_elements_content = xml_file.get_custom_elements_children_and_grandchildren(custom_element_name)

    if not xml_file.check_if_element_exists_with_custom_attrib(custom_element=custom_element_name,
                                                               custom_attrib=custom_attr_name,
                                                               attrib_value=attribute_value):
        raise ObjectNotFoundInXmlFile('Object with attribute value: {} not found in file: {}'.format(
            attribute_value, xml_file_name))

    if not _check_if_custom_element_have_location_info(custom_elements_content=custom_elements_content,
                                                       custom_element_name=custom_element_name,
                                                       custom_attr_name=custom_attr_name,
                                                       attr_value=attribute_value):
        raise LocationInfoNotFoundInXmlFile(
            'No location info in object with attribute value: {} in file: {}'.format(attribute_value,
                                                                                     xml_file_name))


@log_input_and_output
def _verify_if_geolocation_objects_do_not_exist(xml_file, xml_file_name, custom_element_name, custom_attr_name,
                                                attribute_value):
    if xml_file.check_if_element_exists_with_custom_attrib(custom_element=custom_element_name,
                                                           custom_attrib=custom_attr_name,
                                                           attrib_value=attribute_value):
        raise ObjectShouldNotBeFoundInXmlFile(
            'Object with attribute value: {} should not be found in file: {}'.format(
                attribute_value, xml_file_name))
